update ${dynamicTableNameProxy.collaborateScheduleItem}
set schedule_Quantity = COALESCE(schedule_Quantity) + #{num},
    schedule_Flag= true
where primary_key = #{id}
  and COALESCE(schedule_Quantity) + #{num} <= order_quantity

mapper.select:
select contract_code, sell_order_code, contract_number, max(create_time) , min(display_delivery) display_delivery
from ${dynamicTableNameProxy.collaborateScheduleItem} a
where collaborate_type = 0
and enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
and delete_flag = false
and can_produce = true

    and contract_code = #{data.contractCode}




    and contract_number like '%'|| #{data.contractNumber} ||'%'




    and delivery >= #{data.startTime}



    and delivery <= #{data.endTime}



    and exists(
    select 1 from ${dynamicTableNameProxy.sellOrder} b
    where b.primary_key=a.sell_order_code
    and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag = false
    and b.collaborate_latest_process=#{data.process}
    )






    and exists( select 1 from ${dynamicTableNameProxy.collaborateProduceDistribute} b
    where b.Bind_Code=a.primary_key
    and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag = false
    and b.Manage_User_Code= ${dynamicTableNameProxy.currentCode}
    )






    and exists(
    select 1 from ${dynamicTableNameProxy.sellOrder} b where
    a.sell_order_code = b.primary_key
    and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
    and b.delete_flag = false
    and b.collaborate_latest_process in

        #{pro}

    )



group by contract_code, sell_order_code, contract_number
order by max(create_time) desc

