mapper.select:
WITH mainInfo AS ( SELECT contract_number, contract_code, sell_order_code, SUM(outbound_quantity) AS total_outbound, SUM(order_quantity) AS total_order, (SUM(outbound_quantity) < SUM(order_quantity)) AS canOut, MIN(display_Delivery) AS display_Delivery, NOT BOOL_OR(COALESCE(schedule_flag, FALSE)) AS canReturn, MAX(create_time) AS latest_create_time FROM ${dynamicTableNameProxy.collaborateScheduleItem} WHERE delete_flag = false and enterprise_code = #{enterpriseCode} and material_nature is null and collaborate_type = 0
and contract_number ilike '%'|| #{requestData.contractNumber} ||'%'
and delivery >= #{requestData.startTime}
and delivery <= #{requestData.endTime}
GROUP BY contract_number, contract_code, sell_order_code ) select m.*, s.collaborate_latest_process from mainInfo m left join ${dynamicTableNameProxy.sellOrder} s on m.sell_order_code = s.primary_key
and s.collaborate_latest_process in
#{pro}
ORDER BY m.latest_create_time DESC

select t.primary_key code, t2.pieces_sign AS name from ${dynamicTableNameProxy.productPart} t LEFT JOIN ${dynamicTableNameProxy.productPiece} t2 ON t.pcs = t2.primary_key where t.enterprise_code = #{enterpriseCode}
and t.primary_key in
#{item}

WITH mainInfo AS ( SELECT contract_code, sell_order_code, contract_number, NOT BOOL_OR(COALESCE(schedule_flag, FALSE)) AS canReturn FROM ${dynamicTableNameProxy.collaborateScheduleItem} WHERE delete_flag = false and enterprise_code = #{enterpriseCode}
and contract_number ilike '%'|| #{param.contractNumber} ||'%'
and delivery >= #{param.startTime}
and delivery <= #{param.endTime}
GROUP BY contract_code, sell_order_code, contract_number order by contract_code desc ) select m.*, sellOrder.collaborate_latest_process, sellOrder.contract_remark FROM mainInfo m LEFT JOIN ${dynamicTableNameProxy.sellOrder} sellOrder ON m.sell_order_code = sellOrder.primary_key
AND sellOrder.collaborate_latest_process IN
#{processCondition}
order by sell_order_code desc

SELECT scheduleItem.collaborate_material, SUM(scheduleItem.order_quantity) as orderQuantity, SUM(scheduleItem.order_quantity - scheduleItem.schedule_quantity - COALESCE( scheduleItem.material_purchase_quantity, 0) - COALESCE( scheduleItem.material_out_bound_quantity, 0) - COALESCE(scheduleItem.ingredient_out_quantity, 0)) as canEnquiryNum FROM ${collaborateScheduleItemTable} scheduleItem LEFT JOIN ${productPartTableName} pp ON scheduleItem.collaborate_material = pp.primary_key WHERE scheduleItem.delete_flag = false and scheduleItem.enterprise_code = #{enterpriseCode} and scheduleItem.collaborate_type = 0
AND scheduleItem.latest_progress IN
#{processCondition}
and (scheduleItem.order_quantity - COALESCE( scheduleItem.outbound_quantity, 0)) > 0 and (scheduleItem.order_quantity - scheduleItem.schedule_quantity - COALESCE( scheduleItem.material_purchase_quantity, 0) - COALESCE( scheduleItem.material_out_bound_quantity, 0) - COALESCE(scheduleItem.ingredient_out_quantity, 0)) > 0
and scheduleItem.delivery >= #{param.startTime}
and scheduleItem.delivery <= #{param.endTime}
and (pp.model like '%'|| #{param.materialKeyWord} ||'%' or pp.product_part_sign like '%'|| #{param.materialKeyWord} ||'%' or pp.unity_no like '%'|| #{param.materialKeyWord} ||'%' )
GROUP BY scheduleItem.collaborate_material

SELECT scheduleItem.collaborate_material, SUM(scheduleItem.order_quantity - scheduleItem.schedule_quantity) as demandQuantity, SUM(scheduleItem.order_quantity - scheduleItem.schedule_quantity - COALESCE( scheduleItem.material_purchase_quantity, 0) - COALESCE( scheduleItem.material_out_bound_quantity, 0) - COALESCE(scheduleItem.ingredient_out_quantity, 0)) as canEnquiryNum FROM ${collaborateScheduleItemTable} scheduleItem LEFT JOIN ${productPartTableName} pp ON scheduleItem.collaborate_material = pp.primary_key WHERE scheduleItem.delete_flag = false and scheduleItem.enterprise_code = #{enterpriseCode} and scheduleItem.collaborate_type = 1
AND scheduleItem.latest_progress IN
#{processCondition}
and (scheduleItem.product_out_finish IS NULL OR scheduleItem.product_out_finish = 'f') and (scheduleItem.order_quantity - scheduleItem.schedule_quantity - COALESCE( scheduleItem.outbound_quantity, 0)) > 0 and (scheduleItem.order_quantity - scheduleItem.schedule_quantity - COALESCE( scheduleItem.material_purchase_quantity, 0) - COALESCE( scheduleItem.material_out_bound_quantity, 0) - COALESCE(scheduleItem.ingredient_out_quantity, 0)) > 0
and scheduleItem.delivery >= #{param.startTime}
and scheduleItem.delivery <= #{param.endTime}
and (pp.model like '%'|| #{param.materialKeyWord} ||'%' or pp.product_part_sign like '%'|| #{param.materialKeyWord} ||'%' or pp.unity_no like '%'|| #{param.materialKeyWord} ||'%' )
GROUP BY scheduleItem.collaborate_material

SELECT collaborate_material,
       SUM(order_quantity)    as totalProductOrderQuantity,
       SUM(schedule_quantity) as totalProductScheduleQuantity
FROM ${dynamicTableNameProxy.collaborateScheduleItem}
WHERE delete_flag = false
  and enterprise_code = #{enterpriseCode}
  and collaborate_material = #{collaborateMaterial}
  and collaborate_type = 0
  and (outbound_quantity < order_quantity)
GROUP BY collaborate_material

SELECT pp.primary_key as collaborateMaterial, pp.unity_no, pp.product_part_sign as name, pp.model, SUM(COALESCE(scheduleItem.outbound_quantity, 0)) AS outboundQuantity, SUM(COALESCE(scheduleItem.order_quantity, 0)) - SUM(COALESCE(scheduleItem.outbound_quantity, 0)) AS difference FROM ${collaborateScheduleItemTableName} scheduleItem LEFT JOIN ${productPartTableName} pp ON scheduleItem.collaborate_material = pp.primary_key WHERE scheduleItem.enterprise_code = #{enterpriseCode} and scheduleItem.delete_flag = false
AND scheduleItem.create_time >= #{requestData.startTime}
AND scheduleItem.create_time <= #{requestData.endTime}
GROUP BY pp.primary_key, pp.unity_no, pp.product_part_sign, pp.model order by difference desc

SELECT
collaborate_material as code,
MIN(display_Delivery) AS name
FROM ${tableName}
WHERE collaborate_material IN

    #{collaborateMaterial}

AND collaborate_type = #{collaborateType}
AND display_delivery IS NOT NULL
AND enterprise_code = #{enterpriseCode}
AND (order_quantity - COALESCE(outbound_quantity, 0)) > 0
AND (order_quantity - schedule_quantity - COALESCE(material_purchase_quantity, 0) -
COALESCE(material_out_bound_quantity, 0) - COALESCE(ingredient_out_quantity, 0)) > 0
GROUP BY collaborate_material

SELECT contract_code,
NOT BOOL_OR(COALESCE(schedule_flag, FALSE)) AS canReturn
FROM ${dynamicTableNameProxy.collaborateScheduleItem}
WHERE delete_flag = false
and enterprise_code = #{enterpriseCode}
AND contract_code IN

    #{contractCode}

GROUP BY contract_code

SELECT collaborate_material as collaborateMaterial,
contract_code as contractCode,
SUM(order_quantity - COALESCE(schedule_quantity, 0)) AS demandQuantity
FROM ${dynamicTableNameProxy.collaborateScheduleItem}
WHERE delete_flag = false
AND enterprise_code = #{enterpriseCode}
AND (order_quantity - COALESCE(schedule_quantity, 0)) > 0
AND collaborate_material IN

    #{materialCode}

GROUP BY collaborate_material,contract_code
